contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address to, uint256 amount) public {
        require(to != address(0));
        require(!c.frozenAccount(address(this)));
        require(!c.frozenAccount(to));
        uint256 senderBalBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 toBalBefore = c.balanceOf(to); if (__ESBMC_reverted()) return;
        require(senderBalBefore >= amount);
        bool ok = c.transfer(to, amount); if (__ESBMC_reverted()) return;
        assert(ok && c.balanceOf(address(this)) == senderBalBefore - amount && c.balanceOf(to) == toBalBefore + amount && c.totalSupply() == c.totalSupply());
    }
    receive() external payable {}
}

