        vm.assume(!c.frozenAccount(address(this)));
        vm.assume(!c.frozenAccount(to));
        uint256 senderBalBefore;
        try c.balanceOf(address(this)) returns (uint256 __r) { senderBalBefore = __r; } catch { return; }
        uint256 toBalBefore;
        try c.balanceOf(to) returns (uint256 __r) { toBalBefore = __r; } catch { return; }
        vm.assume(senderBalBefore >= amount);
